const KITCH_OFFICE_EMBED='';
let kitchOfficeDecodePromise=null;
function prepareKitchOffice(){
 if(kitchOfficeDecodePromise)return kitchOfficeDecodePromise;
 kitchOfficeDecodePromise=new Promise((resolve,reject)=>{
  const work=()=>{try{const binary=atob(KITCH_OFFICE_EMBED);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);resolve(new TextDecoder().decode(bytes))}catch(e){kitchOfficeDecodePromise=null;reject(e)}};
  if('requestIdleCallback' in window)requestIdleCallback(work,{timeout:1200});else setTimeout(work,0);
 });return kitchOfficeDecodePromise;
}
function openKitchMainOffice(){
 const box=document.getElementById('kitchOfficeOverlay'),frame=document.getElementById('kitchOfficeFrame');
 box.classList.add('open');document.body.style.overflow='hidden';
 if(frame.dataset.initialized==='yes')return;
 if(frame.dataset.initialized==='loading')return;
 frame.dataset.initialized='loading';frame.classList.remove('ready');
 prepareKitchOffice().then(html=>{frame.srcdoc=html;frame.dataset.initialized='yes'}).catch(e=>{
  console.error('Main Office loading failed',e);frame.dataset.initialized='';
  document.getElementById('kitchOfficeLoading').textContent='Unable to load Main Office. Please refresh and try again.';
 });
}
function closeKitchMainOffice(){document.getElementById('kitchOfficeOverlay').classList.remove('open');document.body.style.overflow='';document.getElementById('login')?.classList.remove('hidden')}
window.addEventListener('message',function(event){
  const frame=document.getElementById('kitchOfficeFrame');
  if(!frame||event.source!==frame.contentWindow||event.data?.type!=='KITCH_OFFICE_SIGNED_OUT')return;
  closeKitchMainOffice();
  // The cached office has already reset its signed-out view.
  // Its own Supabase auth listener controls the signed-out view.
  try{session=null;currentStaff=null;teamCloudAuth=null;cloud={restaurant_id:null,branch_id:null,workspace_code:null,user:null};}catch(e){}
  try{
    document.getElementById('app')?.classList.add('hidden');
    document.getElementById('login')?.classList.remove('hidden');
    document.body.style.overflow='';
    document.documentElement.classList.remove('modal-open');
    document.body.classList.remove('modal-open');
  }catch(e){}
  try{closePublicModal();}catch(e){}
  window.scrollTo(0,0);
});

